import { useEffect, useState, useCallback, useMemo } from "react"
import { Link } from "@tanstack/react-router"
import { Plus, ArrowUpRight } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Button } from "../components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import SectionCards from "../components/SectionCards"
import ChartAreaInteractive from "../components/ChartAreaInteractive"
import DataTable from "../components/DataTable"
import type { IWalletTransaction, WaveResponse, ITransaction } from "@/types"
import { formatCurrency } from "@/lib/utils"

export default function HomePage() {
  const { data: session } = useSession()
  const user = session!.user
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [loadingAccounts, setLoadingAccounts] = useState(true)
  const [loadingTransactions, setLoadingTransactions] = useState(true)

  const userAccountIds = useMemo(() => new Set(accounts.map((a) => a.id)), [accounts])

  const fetchAccounts = useCallback(async () => {
    setLoadingAccounts(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: WaveResponse<IWalletTransaction[]> = await res.json()
      setAccounts(json.ok ? json.data : [])
    } catch {
      setAccounts([])
    } finally {
      setLoadingAccounts(false)
    }
  }, [user.id])

  const fetchTransactions = useCallback(async () => {
    setLoadingTransactions(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/transactions`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: WaveResponse<ITransaction[]> = await res.json()
      if (json.ok) {
        const sorted = json.data.sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        )
        setTransactions(sorted)
      }
    } catch {
      setTransactions([])
    } finally {
      setLoadingTransactions(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
    fetchTransactions()
  }, [fetchAccounts, fetchTransactions])

  const totalBalance = accounts.reduce((sum, a) => sum + a.balance, 0)

  const dailyVolumes = useMemo(() => {
    const map = new Map<string, number>()
    for (const tx of transactions) {
      const day = tx.createdAt.slice(0, 10)
      map.set(day, (map.get(day) ?? 0) + Number(tx.amount))
    }
    return Array.from(map.entries())
      .map(([date, volume]) => ({ date, volume }))
      .sort((a, b) => a.date.localeCompare(b.date))
  }, [transactions])

  const recentTransactions = useMemo(() => transactions.slice(0, 10), [transactions])

  const successCount = transactions.filter((tx) => tx.status === "success").length
  const pendingCount = transactions.filter((tx) => tx.status === "pending").length
  const totalVolume = transactions.reduce((sum, tx) => sum + Number(tx.amount), 0)

  const cardData = loadingAccounts
    ? []
    : [
        {
          title: "Total Balance",
          value: formatCurrency(totalBalance),
          subtitle: `${accounts.length} account${accounts.length !== 1 ? "s" : ""}`,
          trend: { value: `${accounts.length > 0 ? "+" : ""}${accounts.length}`, positive: accounts.length > 0 },
        },
        {
          title: "Transaction Volume",
          value: formatCurrency(totalVolume),
          subtitle: `${transactions.length} transaction${transactions.length !== 1 ? "s" : ""}`,
        },
        {
          title: "Success Rate",
          value: transactions.length > 0 ? `${Math.round((successCount / transactions.length) * 100)}%` : "\u2014",
          subtitle: `${successCount} of ${transactions.length} succeeded`,
          trend: successCount > 0 ? { value: `${successCount}`, positive: true } : undefined,
        },
        {
          title: "Pending",
          value: String(pendingCount),
          subtitle: pendingCount === 1 ? "1 awaiting confirmation" : `${pendingCount} awaiting confirmation`,
        },
      ]

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">Dashboard</h1>
        <div className="flex items-center gap-3">
          <span className="text-sm text-muted-foreground">{user.email}</span>
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-6xl px-8 py-8 space-y-6">
        <div className="flex items-center gap-2">
          <h2 className="text-sm font-medium text-muted-foreground">
            {new Date().getHours() < 12
              ? "Good morning"
              : new Date().getHours() < 18
                ? "Good afternoon"
                : "Good evening"
            }, {user.name}
          </h2>
        </div>

        <SectionCards data={cardData} />

        <div className="grid grid-cols-2 gap-4">
          <Link
            to="/account"
            search={{ section: "deposit" }}
            className="inline-flex items-center justify-center gap-3 rounded-xl bg-primary text-primary-foreground h-14 text-sm font-semibold transition-colors hover:opacity-90"
          >
            <Plus className="size-4" />
            Add Money
          </Link>
          <Link
            to="/account?section=transfer"
            className="inline-flex items-center justify-center gap-3 rounded-xl bg-surface text-foreground h-14 text-sm font-semibold transition-colors hover:bg-surface-hover border border-border"
          >
            <ArrowUpRight className="size-4" />
            Send Money
          </Link>
        </div>

        <ChartAreaInteractive data={dailyVolumes} />

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-sm font-medium">Recent Transactions</CardTitle>
            <Link
              to="/account/transactions"
              className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
            >
              View all
            </Link>
          </CardHeader>
          <CardContent className="p-0">
            <DataTable
              data={recentTransactions}
              userAccountIds={userAccountIds}
              loading={loadingTransactions}
              emptyMessage="No transactions yet. Deposit funds to get started."
              onRowClick={(tx) => window.location.href = `/transactions/${tx.id}`}
            />
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
      </footer>
    </>
  )
}

import { useEffect, useState, useRef, useCallback } from "react"
import { Link } from "@tanstack/react-router"
import { signOut, useSession } from "../lib/auth-client"
import { Card, CardContent } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface Notification {
  id: string
  title: string
  message: string
  type: "info" | "warning" | "error"
  timestamp: string
  read: boolean
}

interface StandardResponse<T> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

function statusVariant(status: string): "default" | "secondary" | "destructive" {
  if (status === "connected") return "default"
  if (status === "disconnected") return "destructive"
  return "secondary"
}

function statusLabel(status: string): string {
  if (status === "connected") return "Live"
  if (status === "disconnected") return "Disconnected"
  return "Connecting"
}

export default function NotificationPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [connectionStatus, setConnectionStatus] = useState<"connected" | "disconnected" | "connecting">("connecting")
  const eventSourceRef = useRef<EventSource | null>(null)
  const retryCountRef = useRef(0)

  const fetchInitial = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/notification/users/${user.id}/notifications?limit=50`)
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const json: StandardResponse<Notification[]> = await response.json()
      setNotifications(json.data ?? [])
      setError(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load")
      setNotifications([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const connectSSE = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
    }

    setConnectionStatus("connecting")
    const es = new EventSource(`/api/notification/users/${user.id}/notifications/stream`)
    eventSourceRef.current = es

    es.onopen = () => {
      setConnectionStatus("connected")
      retryCountRef.current = 0
    }

    es.onmessage = (event) => {
      try {
        const parsed = JSON.parse(event.data)
        const items: Notification[] = parsed.result ?? parsed.data ?? []
        if (items.length > 0) {
          setNotifications((prev) => {
            const existing = new Set(prev.map((n) => n.id))
            const newItems = items.filter((n) => !existing.has(n.id))
            return [...newItems, ...prev].slice(0, 50)
          })
        }
      } catch {
        // ping or parse error - ignore
      }
    }

    es.onerror = () => {
      setConnectionStatus("disconnected")
      es.close()
      eventSourceRef.current = null

      const delay = Math.min(1000 * 2 ** retryCountRef.current, 30000)
      retryCountRef.current += 1
      setTimeout(connectSSE, delay)
    }
  }, [user.id])

  useEffect(() => {
    fetchInitial()
    connectSSE()
    return () => {
      if (eventSourceRef.current) eventSourceRef.current.close()
    }
  }, [fetchInitial, connectSSE])

  const dismissNotification = async (id: string) => {
    try {
      const res = await fetch(`/api/notification/users/${user.id}/notifications/${id}`, {
        method: "DELETE",
      })
      if (res.ok) {
        setNotifications((prev) => prev.filter((n) => n.id !== id))
      }
    } catch {
      // silently fail
    }
  }

  const markRead = async (id: string) => {
    try {
      const res = await fetch(`/api/notification/users/${user.id}/notifications/${id}/read`, {
        method: "PATCH",
      })
      if (res.ok) {
        setNotifications((prev) =>
          prev.map((n) => (n.id === id ? { ...n, read: true } : n))
        )
      }
    } catch {
      // silently fail
    }
  }

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">Notifications</h1>
        <div className="flex items-center gap-3">
          <Badge variant={statusVariant(connectionStatus)}>
            <span className={`mr-1.5 h-1.5 w-1.5 rounded-full inline-block ${
              connectionStatus === "connected" ? "bg-current" :
              connectionStatus === "disconnected" ? "bg-current" :
              "bg-current animate-a-spin"
            }`} />
            {statusLabel(connectionStatus)}
          </Badge>
          <span className="text-sm text-muted-foreground">{user.email}</span>
          <Link
            to="/notifications/preferences"
            className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
          >
            Preferences
          </Link>
          <Button variant="outline" size="sm" onClick={fetchInitial}>
            Refresh
          </Button>
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {loading && (
          <div className="flex flex-col gap-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} data-testid="skeleton-card" className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10 border-2 border-destructive/30 text-destructive text-lg font-bold">
              !
            </div>
            <p className="text-muted-foreground">{error}</p>
            <Button variant="outline" onClick={fetchInitial}>
              Retry
            </Button>
          </div>
        )}

        {!loading && !error && notifications.length === 0 && (
          <div className="flex flex-col items-center justify-center gap-2 py-16 text-center">
            <h2 className="text-base font-semibold text-muted-foreground">No notifications</h2>
            <p className="text-sm text-muted-foreground/60">
              New notifications will appear here in real time.
            </p>
          </div>
        )}

        {!loading && !error && notifications.length > 0 && (
          <div className="flex flex-col gap-2">
            {notifications.map((n) => (
              <div
                key={n.id}
                data-testid="notification-card"
                data-read={n.read}
                className={`group rounded-xl px-4 py-3.5 transition-colors ${
                  n.read
                    ? "bg-surface opacity-70 hover:opacity-100"
                    : "bg-accent-subtle"
                }`}
              >
                <div className="flex gap-3">
                  <span
                    className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${
                      n.type === "info" ? "bg-primary" :
                      n.type === "warning" ? "bg-warning" :
                      "bg-error"
                    }`}
                  />
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-start gap-4 mb-0.5">
                      <h3 className={`text-sm ${n.read ? "font-medium" : "font-semibold"} text-foreground`}>
                        {n.title}
                      </h3>
                      <time className="shrink-0 text-xs text-muted-foreground/70 font-mono">
                        {new Date(n.timestamp).toLocaleTimeString(undefined, {
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </time>
                    </div>
                    <p className="text-sm text-muted-foreground leading-relaxed line-clamp-2">
                      {n.message}
                    </p>
                    <div className="flex gap-2 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      {!n.read && (
                        <Button variant="ghost" size="xs" onClick={() => markRead(n.id)}>
                          Mark read
                        </Button>
                      )}
                      <Button variant="ghost" size="xs" onClick={() => dismissNotification(n.id)}>
                        Dismiss
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Notification Center</span>
        <span>{notifications.length} notifications</span>
      </footer>
    </>
  )
}

import { useEffect, useState, useCallback } from "react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Skeleton } from "../components/ui/skeleton"

interface NotificationPreference {
  userId: string
  eventType: "deposit" | "transfer_incoming" | "transfer_outgoing"
  enabled: boolean
}

const EVENT_LABELS: Record<string, string> = {
  deposit: "Deposits",
  transfer_incoming: "Money Received",
  transfer_outgoing: "Money Sent",
}

const EVENT_DESCRIPTIONS: Record<string, string> = {
  deposit: "When money is added to your account",
  transfer_incoming: "When someone sends you money",
  transfer_outgoing: "When you send money to someone",
}

export default function NotificationPreferencesPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [preferences, setPreferences] = useState<NotificationPreference[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const fetchPreferences = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetch(`/api/notification/users/${user.id}/notification-preferences`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json = await res.json()
      setPreferences(json.data ?? [])
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load preferences")
    } finally {
      setLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchPreferences()
  }, [fetchPreferences])

  const togglePreference = async (eventType: string, currentEnabled: boolean) => {
    setSaving(eventType)
    try {
      const res = await fetch(`/api/notification/users/${user.id}/notification-preferences`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ eventType, enabled: !currentEnabled }),
      })
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json = await res.json()
      setPreferences((prev) => {
        const existing = prev.find((p) => p.eventType === eventType)
        if (existing) {
          return prev.map((p) => (p.eventType === eventType ? json.data : p))
        }
        return [...prev, json.data]
      })
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update preference")
    } finally {
      setSaving(null)
    }
  }

  const allEventTypes = ["deposit", "transfer_incoming", "transfer_outgoing"]
  const preferenceMap = new Map(preferences.map((p) => [p.eventType, p]))

  return (
    <>
      <header className="flex items-center justify-between px-8 py-5 border-b border-border">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">Notification Preferences</h1>
        <span className="text-sm text-muted-foreground">{user.email}</span>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {loading && (
          <div className="flex flex-col gap-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <p className="text-muted-foreground">{error}</p>
            <Button variant="outline" onClick={fetchPreferences}>Retry</Button>
          </div>
        )}

        {!loading && !error && (
          <div className="flex flex-col gap-2">
            {allEventTypes.map((eventType) => {
              const pref = preferenceMap.get(eventType)
              const enabled = pref?.enabled ?? true
              return (
                <Card key={eventType}>
                  <CardContent className="flex items-center justify-between py-4 px-5">
                    <div className="space-y-0.5">
                      <p className="text-sm font-medium text-foreground">{EVENT_LABELS[eventType]}</p>
                      <p className="text-xs text-muted-foreground">{EVENT_DESCRIPTIONS[eventType]}</p>
                    </div>
                    <button
                      type="button"
                      role="switch"
                      aria-checked={enabled}
                      disabled={saving === eventType}
                      onClick={() => togglePreference(eventType, enabled)}
                      className={`relative h-6 w-11 rounded-full transition-colors ${
                        saving === eventType ? "opacity-50 pointer-events-none" : ""
                      } ${
                        enabled ? "bg-primary" : "bg-input"
                      }`}
                    >
                      <span
                        className={`block h-5 w-5 rounded-full bg-background shadow-sm transition-transform ${
                          enabled ? "translate-x-[22px]" : "translate-x-[2px]"
                        }`}
                      />
                    </button>
                  </CardContent>
                </Card>
              )
            })}
          </div>
        )}
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Notification Center</span>
        <span>Preferences</span>
      </footer>
    </>
  )
}
